// Post effect CrtSweep (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_period: f32,
  p_sweep: f32,
  p_width: f32,
  p_shift: f32,
  p_split: f32,
  p_glow: f32,
};
@group(1) @binding(0) var<uniform> material: MaterialParams;
fn material_post(in: PostInput) -> vec3f {
  let v0: f32 = in.screen_uv.y;
  let v1: f32 = (v0 * 220.0);
  let v2: f32 = (in.time * 40.0);
  let v3: f32 = (v1 + v2);
  let v4: f32 = sin(v3);
  let v5: f32 = (v4 * material.p_shift);
  let v6: f32 = in.size.y;
  let v7: f32 = (v6 / 1080.0);
  let v8: f32 = (v5 * v7);
  let v9: f32 = (in.time / material.p_period);
  let v10: f32 = fract(v9);
  let v11: f32 = (v10 * material.p_period);
  let v12: f32 = (v11 / material.p_sweep);
  let v13: f32 = (material.p_width * 2.0);
  let v14: f32 = (v13 + 1.0);
  let v15: f32 = (v12 * v14);
  let v16: f32 = (v15 - material.p_width);
  let v17: f32 = (v0 - v16);
  let v18: f32 = abs(v17);
  let v19: f32 = smoothstep(0.0, material.p_width, v18);
  let v20: f32 = (v19 * -1.0);
  let v21: f32 = (v20 + 1.0);
  let v22: f32 = (v8 * v21);
  let v23: vec2f = vec2f(v22, 0.0);
  let v24: vec2f = (v23 * in.texel);
  let v25: vec2f = (in.screen_uv + v24);
  let v26: f32 = (material.p_split * v7);
  let v27: f32 = (v26 * v21);
  let v28: vec2f = vec2f(v27, 0.0);
  let v29: vec2f = (v28 * in.texel);
  let v30: vec2f = (v25 + v29);
  let v31: vec3f = post_color(v30);
  let v32: f32 = v31.x;
  let v33: vec3f = post_color(v25);
  let v34: f32 = v33.y;
  let v35: vec2f = (v25 - v29);
  let v36: vec3f = post_color(v35);
  let v37: f32 = v36.z;
  let v38: vec3f = vec3f(v32, v34, v37);
  let v39: f32 = (v21 * material.p_glow);
  let v40: f32 = (v0 * v6);
  let v41: f32 = (v40 * 1.6);
  let v42: f32 = sin(v41);
  let v43: f32 = (v42 * 0.5);
  let v44: f32 = (v43 + 0.5);
  let v45: f32 = (v44 * 0.5);
  let v46: f32 = (v45 + 0.5);
  let v47: f32 = (v39 * v46);
  let v48: f32 = (v47 + 1.0);
  let v49: f32 = clamp(v48, 1.0, 2.0);
  let v50: vec3f = (v38 * v49);
  return v50;
}
